using System;
using System.IO;
using System.Linq;
using CountToZero;
using TMPro;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.UI;
[InitializeOnLoad]
public static class ExpansionUpgrade
{
 static ExpansionUpgrade(){EditorApplication.update+=Poll;}
 static void Poll(){if(!File.Exists("Temp/ctz-expansion.request")||EditorApplication.isPlayingOrWillChangePlaymode||EditorApplication.isCompiling||EditorApplication.isUpdating)return;File.Delete("Temp/ctz-expansion.request");try{Run();}catch(Exception e){File.WriteAllText("Documentation/expansion-build.txt",e.ToString());Debug.LogException(e);}}
 static T Add<T>(GameObject o)where T:Component{var c=o.GetComponent<T>();return c!=null?c:o.AddComponent<T>();}
 static void Wire(UnityEngine.Object o,string field,UnityEngine.Object value){var s=new SerializedObject(o);s.FindProperty(field).objectReferenceValue=value;s.ApplyModifiedPropertiesWithoutUndo();}
 static void Array(UnityEngine.Object o,string field,UnityEngine.Object[] values){var s=new SerializedObject(o);var p=s.FindProperty(field);p.arraySize=values.Length;for(int i=0;i<values.Length;i++)p.GetArrayElementAtIndex(i).objectReferenceValue=values[i];s.ApplyModifiedPropertiesWithoutUndo();}
 static Sprite Import(string path){var i=(TextureImporter)AssetImporter.GetAtPath(path);i.textureType=TextureImporterType.Sprite;i.spriteImportMode=SpriteImportMode.Single;i.filterMode=FilterMode.Point;i.textureCompression=TextureImporterCompression.Uncompressed;i.mipmapEnabled=false;i.SaveAndReimport();return AssetDatabase.LoadAssetAtPath<Sprite>(path);}
 [MenuItem("Count To Zero/Build Battle Expansion")]
 public static void Run(){AssetDatabase.Refresh();var comic=Enumerable.Range(1,3).Select(i=>Import("Assets/GameAssets/Sprites/cutscene_"+i+".png")).ToArray();var frames=new[]{"assistant_green","assistant_gold"}.SelectMany(n=>PresentationUpgrade.SliceWalkFrames("Assets/GameAssets/Sprites/man/"+n+".png").OrderBy(s=>s.name.StartsWith("Front")?0:1).ThenBy(s=>s.name)).ToArray();
 var scene=EditorSceneManager.OpenScene("Assets/Scenes/CountToZero.unity");var g=UnityEngine.Object.FindFirstObjectByType<GameManager>();var expansion=Add<BattleExpansion>(g.gameObject);Array(expansion,"assistantFrames",frames);
 var texture=new Texture2D(1,1);texture.SetPixel(0,0,Color.white);texture.Apply();string pixelPath="Assets/GameAssets/Sprites/ExpansionPixel.png";File.WriteAllBytes(pixelPath,texture.EncodeToPNG());AssetDatabase.ImportAsset(pixelPath);var pixel=Import(pixelPath);var ti=(TextureImporter)AssetImporter.GetAtPath(pixelPath);ti.spritePixelsPerUnit=1;ti.SaveAndReimport();Wire(expansion,"pixel",AssetDatabase.LoadAssetAtPath<Sprite>(pixelPath));
 string matPath="Assets/GameAssets/Materials/ExpansionBeam.mat";var mat=AssetDatabase.LoadAssetAtPath<Material>(matPath);if(mat==null){mat=new Material(Shader.Find("Sprites/Default"));AssetDatabase.CreateAsset(mat,matPath);}Wire(expansion,"lineMaterial",mat);
 var canvas=UnityEngine.Object.FindObjectsByType<Canvas>(FindObjectsSortMode.None).First(c=>c.renderMode!=RenderMode.WorldSpace);var notice=GameObject.Find("Assistant Loss Notice");if(notice==null){var r=CampaignExpansionUI.Rect("Assistant Loss Notice",canvas.transform,new Vector2(-20,145),new Vector2(440,85));r.anchorMin=r.anchorMax=r.pivot=new Vector2(1,0);notice=r.gameObject;}var text=Add<TextMeshProUGUI>(notice);text.font=TypographyUpgrade.BodyFont;text.fontSize=26;text.alignment=TextAlignmentOptions.BottomRight;text.color=Color.white;text.text="";Wire(expansion,"lossNotice",text);
 var boss=new SerializedObject(g.Boss);var patterns=boss.FindProperty("patterns");patterns.arraySize=25;string[] names={"SQUARE RUSH","SEGMENTED VIRUS","HEARTBEAT","ORBIT MINES","ZIGZAG"};for(int i=20;i<25;i++){string path="Assets/GameAssets/Patterns/"+i+"_"+names[i-20].Replace(' ','_')+".asset";var p=AssetDatabase.LoadAssetAtPath<BossPatternDefinition>(path);if(p==null){p=ScriptableObject.CreateInstance<BossPatternDefinition>();AssetDatabase.CreateAsset(p,path);}p.displayName=names[i-20];p.shot=(BossShot)i;p.motion=i==20?BossMotion.SquareRush:i==21?BossMotion.Serpent:BossMotion.FigureEight;p.interval=i==21?.75f:1.1f;p.speed=3.5f;p.count=12;EditorUtility.SetDirty(p);patterns.GetArrayElementAtIndex(i).objectReferenceValue=p;}boss.ApplyModifiedPropertiesWithoutUndo();
 foreach(var obstacle in UnityEngine.Object.FindObjectsByType<ArenaObstacle>(FindObjectsInactive.Include,FindObjectsSortMode.None)){var so=new SerializedObject(obstacle);var warning=(GameObject)so.FindProperty("warning").objectReferenceValue;foreach(var renderer in warning.GetComponentsInChildren<Renderer>())renderer.enabled=false;warning.transform.localRotation=Quaternion.identity;var ring=warning.transform.Find("Red Drop Circle");if(ring==null){ring=new GameObject("Red Drop Circle").transform;ring.SetParent(warning.transform,false);}var line=Add<LineRenderer>(ring.gameObject);line.enabled=true;line.sharedMaterial=AssetDatabase.LoadAssetAtPath<Material>("Assets/GameAssets/Materials/CircuitRedLaser.mat");line.useWorldSpace=false;line.loop=true;line.positionCount=40;line.widthMultiplier=.05f;line.startColor=line.endColor=Color.red;for(int n=0;n<40;n++){float a=n*Mathf.PI/20;line.SetPosition(n,new Vector3(Mathf.Cos(a)*.55f,.05f,Mathf.Sin(a)*.55f));}}
 EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);
 foreach(var name in new[]{"Title","Story","StoryEnd","CountToZero"}){scene=EditorSceneManager.OpenScene("Assets/Scenes/"+name+".unity");var owner=name=="CountToZero"?UnityEngine.Object.FindFirstObjectByType<GameManager>().gameObject:UnityEngine.Object.FindFirstObjectByType<CampaignScreen>().gameObject;var ui=Add<CampaignExpansionUI>(owner);Array(ui,"comic",comic);Wire(ui,"credits",AssetDatabase.LoadAssetAtPath<TextAsset>("Assets/GameAssets/asset_credits.txt"));var b=UnityEngine.Object.FindObjectsByType<Button>(FindObjectsInactive.Include,FindObjectsSortMode.None).First();Wire(ui,"panelSprite",(b.targetGraphic as Image).sprite);EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);}
 AssetDatabase.SaveAssets();EditorSceneManager.OpenScene("Assets/Scenes/Title.unity");File.WriteAllText("Documentation/expansion-build.txt","PASS: 25 patterns, assistants, lightning, red drop rings, credits, difficulty and 4:3 comic scenes authored.");}
}
